from fastapi import Depends, FastAPI, HTTPException, Query
from pydantic import BaseModel, Field

app = FastAPI()


# --- Models ---
class TodoCreate(BaseModel):
    title: str = Field(min_length=1, max_length=100)
    done: bool = False


class TodoUpdate(BaseModel):
    title: str | None = Field(default=None, min_length=1, max_length=100)
    done: bool | None = None


class Todo(BaseModel):
    id: int
    title: str
    done: bool


# --- In-memory storage ---
todos: dict[int, Todo] = {}
next_id = 1


# --- Dependencies ---
def get_todo_or_404(todo_id: int) -> Todo:
    todo = todos.get(todo_id)
    if todo is None:
        raise HTTPException(status_code=404, detail="Todo not found")
    return todo


def pagination(
    skip: int = Query(default=0, ge=0),
    limit: int = Query(default=10, ge=1, le=100),
) -> dict:
    return {"skip": skip, "limit": limit}


# --- Routes ---
@app.get("/todos", response_model=list[Todo])
def list_todos(done: bool | None = None, page: dict = Depends(pagination)):
    items = list(todos.values())
    if done is not None:
        items = [t for t in items if t.done == done]
    return items[page["skip"] : page["skip"] + page["limit"]]


@app.get("/todos/{todo_id}", response_model=Todo)
def read_todo(todo: Todo = Depends(get_todo_or_404)):
    return todo


@app.post("/todos", response_model=Todo, status_code=201)
def create_todo(data: TodoCreate):
    global next_id
    todo = Todo(id=next_id, **data.model_dump())
    todos[todo.id] = todo
    next_id += 1
    return todo


@app.put("/todos/{todo_id}", response_model=Todo)
def replace_todo(data: TodoCreate, todo: Todo = Depends(get_todo_or_404)):
    new_todo = Todo(id=todo.id, **data.model_dump())
    todos[todo.id] = new_todo
    return new_todo


@app.patch("/todos/{todo_id}", response_model=Todo)
def update_todo(changes: TodoUpdate, todo: Todo = Depends(get_todo_or_404)):
    data = changes.model_dump(exclude_unset=True)
    updated = todo.model_copy(update=data)
    todos[todo.id] = updated
    return updated


@app.delete("/todos/{todo_id}", status_code=204)
def delete_todo(todo: Todo = Depends(get_todo_or_404)):
    del todos[todo.id]

